with app.app_context():
    db.create_all()

# Definición de la vista de comentarios
@app.route('/api/comments', methods=['GET'])
def get_comments():
    comments = Comment.query.order_by(Comment.id.desc()).all()
    return jsonify([{'id': comment.id, 'text': comment.comment_text} for comment in comments])

# Registro del usuario
@app.route('/api/users', methods=['POST'])
def register_user():
    data = request.get_json()
    if not data or not data['username']:
        return jsonify({'error': 'Username is required'}), 400
    user = User(username=data['username'])
    db.session.add(user)
    db.session.commit()
    return jsonify({'success': True})

# Formulario de subir un comentario
@app.route('/api/submit', methods=['POST'])
def submit_comment():
    data = request.get_json()
    if not data or not data.get('comment_text'):
        return jsonify({'error': 'Comment text is required'}), 400
    comment = Comment(comment_text=data.get('comment_text'))
    comment.user_id = data.get('user_id')
    db.session.commit()
    return jsonify({'success': True})

# Endpoint para una búsqueda de comments
@app.route('/api/search', methods=['GET'])
def search_comments():
    query = request.args.get('query')
    comments = Comment.query.filter(Comment.comment_text.ilike(f'%{query}%')).order_by(Comment.id.desc()).all()
    return jsonify([{'id': comment.id, 'text': comment.comment_text} for comment in comments])

# Endpoint para una búsqueda de comments por ID
@app.route('/api/id/<int:id>', methods=['GET'])
def get_comment(id):
    comment = Comment.query.get_or_404(id)
    if comment:
        return jsonify({'id': comment.id, 'text': comment.comment_text})
    return jsonify({'error': 'Comment not found'}), 404

# Endpoint para una búsqueda de comentarios por ID
@app.route('/api/username/<int:id>', methods=['GET'])
def get_user(id):
    user = User.query.get_or_404(id)
    if user:
        return jsonify({'id': user.id, 'username': user.username})
    return jsonify({'error': 'User not found'}), 404

# Endpoint para un logout
@app.route('/api/logout', methods=['POST'])
def logout():
    return jsonify({'message': 'Logged out successfully!'})

# Endpoint para un rollback
@app.route('/api/rollback', methods=['POST'])
def rollback():
    return jsonify({'message': 'Rollback executed successfully!'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
```

**Punto de Asegurar:** Al usar Flask, se puede elegir usar una base de datos de SQLite o usar una base de datos más fuerte como PostgreSQL. El rastreo de comentarios (comentarios) requiere que el servidor recorde las conexiones de un usuario al momento de suscribirse al servidor.
